export type InstallerErrorCode =
  | "webusb-unsupported"
  | "insecure-context"
  | "no-device"
  | "device-busy"
  | "auth-rejected"
  | "disconnected"
  | "invalid-apk"
  | "push-failed"
  | "install-failed"
  | "unknown";

export class InstallerError extends Error {
  readonly code: InstallerErrorCode;
  readonly detail?: string;

  constructor(code: InstallerErrorCode, message: string, detail?: string) {
    super(message);
    this.name = "InstallerError";
    this.code = code;
    this.detail = detail;
  }
}

export function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return String(error);
}

export function errorDetail(error: unknown): string | undefined {
  if (error instanceof InstallerError) {
    return error.detail ?? error.stack;
  }
  if (error instanceof Error) {
    return error.stack;
  }
  return undefined;
}

export function isUserCancelledPicker(error: unknown): boolean {
  if (error instanceof DOMException && error.name === "NotFoundError") return true;
  if (error instanceof Error && error.name === "NotFoundError") return true;
  return false;
}

export function looksLikeAuthFailure(error: unknown): boolean {
  const message = errorMessage(error).toLowerCase();
  return /unauthor|auth|reject|not allowed|permission denied|cnxn|offline/.test(
    message,
  );
}

export function looksLikeDisconnect(error: unknown): boolean {
  const message = errorMessage(error).toLowerCase();
  const name = error instanceof Error ? error.name : "";
  return (
    name === "NetworkError" ||
    name === "InvalidStateError" ||
    /disconnect|detached|transfer|networkerror|device not found|closed/.test(
      message,
    )
  );
}
